// Parse Firecrawl response and pick best 6 reviews for landing page
const response = $input.first().json;
const data = response.data?.json || response.json || {};

if (!data.reviews || !Array.isArray(data.reviews)) {
  throw new Error('Firecrawl returned no reviews. Response: ' + JSON.stringify(response).slice(0, 500));
}

// Helper: detect Australian reviewers
const isAustralian = (loc) => {
  if (!loc) return false;
  const s = loc.toLowerCase();
  return /\baustralia\b|\bsydney\b|\bmelbourne\b|\bbrisbane\b|\badelaide\b|\bperth\b|\bcanberra\b|\bdarwin\b|\bhobart\b|\bgold coast\b|\bnew south wales\b|\bvictoria\b|\bqueensland\b/.test(s);
};

// Helper: get initials
const getInitials = (name) => {
  return name.split(/\s+/).map(w => w[0]).join('').toUpperCase().slice(0, 2);
};

// Filter: 5-star + min 80 chars + not too long
const quality = data.reviews.filter(r =>
  r.rating === 5 &&
  r.text && r.text.length >= 80 && r.text.length <= 600 &&
  r.name && r.name.length >= 2
);

// Trim quote to 350 chars max (sentence-end)
const trimQuote = (text) => {
  if (text.length <= 350) return text.trim();
  const cut = text.slice(0, 350);
  const lastSentence = Math.max(cut.lastIndexOf('.'), cut.lastIndexOf('!'), cut.lastIndexOf('?'));
  return lastSentence > 200 ? cut.slice(0, lastSentence + 1).trim() : cut.trim() + '...';
};

// Pick: 1 Aussie first (if any), then 5 most recent
const aussie = quality.find(r => isAustralian(r.location));
const nonAussie = quality.filter(r => r !== aussie).slice(0, aussie ? 5 : 6);
const picked = aussie ? [aussie, ...nonAussie] : nonAussie;

// Format to our schema
const formatted = picked.slice(0, 6).map(r => ({
  name: r.name,
  initials: getInitials(r.name),
  location: r.location || 'Verified Traveller',
  isAustralian: isAustralian(r.location),
  tripType: null,
  visitedDate: r.visitedDate || '',
  rating: r.rating,
  quote: trimQuote(r.text),
  profileUrl: r.profileUrl || 'https://www.tripadvisor.com/Attraction_Review-g293924-d29687552-Reviews-My_Viva_Tour-Hanoi.html'
}));

const rankPos = data.rankingPosition || 47;
const rankTotal = data.rankingTotal || 852;

const output = {
  _comment: 'Auto-updated by n8n workflow weekly. Manual edits will be overwritten.',
  lastUpdated: new Date().toISOString(),
  source: {
    url: 'https://www.tripadvisor.com/Attraction_Review-g293924-d29687552-Reviews-My_Viva_Tour-Hanoi.html',
    businessName: 'My Viva Tour',
    city: 'Hanoi'
  },
  rating: {
    value: String(data.rating || 5.0),
    scale: 5,
    count: data.totalReviews || 230,
    distribution: data.ratingDistribution || { excellent: 0, good: 0, average: 0, poor: 0, terrible: 0 }
  },
  award: {
    name: data.award || "Travellers' Choice",
    year: data.awardYear || new Date().getFullYear(),
    issuer: 'Tripadvisor'
  },
  ranking: {
    position: rankPos,
    outOf: rankTotal,
    topPercent: Math.ceil((rankPos / rankTotal) * 100),
    category: 'Hanoi Tour Operators'
  },
  reviews: formatted
};

return [{ json: output }];

// Combine new data + current SHA, encode content as base64
const newData = $('Pick 6 + Format JSON').first().json;
const currentFile = $('GitHub: Get Current SHA').first().json;

const contentStr = JSON.stringify(newData, null, 2) + '\n';
const contentBase64 = Buffer.from(contentStr, 'utf-8').toString('base64');

// Skip commit if content unchanged (decode current, compare)
const currentDecoded = Buffer.from(currentFile.content.replace(/\n/g, ''), 'base64').toString('utf-8');
if (currentDecoded.trim() === contentStr.trim()) {
  return [{ json: { skipped: true, reason: 'No changes detected' } }];
}

return [{ json: {
  message: `chore(reviews): auto-update TripAdvisor reviews — ${newData.rating.count} reviews, ${newData.reviews.length} cards`,
  content: contentBase64,
  sha: currentFile.sha,
  branch: 'main',
  committer: {
    name: 'TripAdvisor Auto-Sync Bot',
    email: 'bot@myvivatour.com'
  }
}}];

// Optional: log success or send notification
const result = $input.first().json;
return [{ json: {
  status: 'committed',
  commit_sha: result.commit?.sha,
  commit_url: result.commit?.html_url,
  file_url: result.content?.html_url,
  message: 'TripAdvisor reviews updated. GitHub Actions will auto-deploy in ~2 minutes.'
}}];
